public sealed class P06RegressionDriver:MonoBehaviour,GameplayInput.IReplaySource {
 const BindingFlags Hidden=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 public string Status {get;private set;}="starting";readonly HashSet<KeyCode> held=new HashSet<KeyCode>();readonly List<string> checks=new List<string>();int downFrame;GameSaveService saves;FourSlotSaveStore oldStore;GameSaveData baseline;string folder;bool cleaning;
 PersistentRuntime Rt=>PersistentRuntime.Instance;GameControlManager Controls=>Rt.GetComponent<GameControlManager>();StoryStateManager Story=>Rt.GetComponent<StoryStateManager>();PlayerController Player=>Controls.ActivePlayer;Scene03Chapter Chapter=>FindAnyObjectByType<Scene03Chapter>();
 public bool Key(KeyCode k)=>held.Contains(k);public bool KeyDown(KeyCode k)=>held.Contains(k)&&Time.frameCount==downFrame;public float Axis(string a)=>a=="Horizontal"?(Key(KeyCode.D)?1:0)-(Key(KeyCode.A)?1:0):a=="Vertical"?(Key(KeyCode.W)?1:0)-(Key(KeyCode.S)?1:0):0;public bool Mouse(int b)=>false;public bool MouseDown(int b)=>false;public bool MouseUp(int b)=>false;public Vector3 Pointer=>Vector3.zero;
 static object Field(object obj,string name)=>obj.GetType().GetField(name,Hidden).GetValue(obj);
 static string PathOf(Transform t)=>t.parent?PathOf(t.parent)+"/"+t.name:t.name;
