 public void Begin(int mode=0){if(GameplayInput.Replay!=null)throw new Exception("Another replay is active");folder=P06Regression.Work+"runtime/camera";Directory.CreateDirectory(folder);saves=Rt.GetComponent<GameSaveService>();oldStore=saves.Store;typeof(GameSaveService).GetProperty("Store").GetSetMethod(true).Invoke(saves,new object[]{new FourSlotSaveStore(folder+"/isolated-slots")});GameplayInput.Replay=this;StartCoroutine(Guard(mode==1?InteractionTests():CameraTests()));}
 IEnumerator Guard(IEnumerator root){var stack=new Stack<IEnumerator>();stack.Push(root);while(stack.Count>0){var top=stack.Peek();bool more=false;object step=null;try{more=top.MoveNext();if(more)step=top.Current;}catch(Exception e){Check(false,"EXCEPTION "+e);break;}if(!more){stack.Pop();continue;}if(step is IEnumerator nested)stack.Push(nested);else yield return step;}Finish();}
 void Finish(){Input();Status="DONE checks="+checks.Count+" failures="+checks.Count(x=>x.StartsWith("FAIL"));File.WriteAllText(folder+"/status.txt",Status);File.WriteAllLines(folder+"/results.txt",checks);Cleanup();Debug.Log(Status);}
 void Cleanup(){if(cleaning)return;cleaning=true;P06EvidenceRecorder.Stop();if(saves&&oldStore!=null)typeof(GameSaveService).GetProperty("Store").GetSetMethod(true).Invoke(saves,new object[]{oldStore});if(ReferenceEquals(GameplayInput.Replay,this))GameplayInput.Replay=null;}
 void OnDestroy(){Cleanup();}
 void Check(bool pass,string s){checks.Add((pass?"PASS ":"FAIL ")+s);File.WriteAllLines(folder+"/results.txt",checks);}
 void Need(bool pass,string s){Check(pass,s);if(!pass)throw new Exception(s);}
 void Label(string s){Status=s;File.WriteAllText(folder+"/status.txt",s);}
 void Input(params KeyCode[] keys){held.Clear();foreach(var k in keys)held.Add(k);downFrame=Time.frameCount+1;}
 IEnumerator Foreground(){while(!Application.isFocused){Label("WAIT Unity Game foreground; pause rules preserved");yield return null;}if(GamePause.IsPaused)Rt.GetComponent<GamePause>().SetPaused(false);}
 IEnumerator Wait(float n){float t=0;while(t<n){if(GamePause.IsPaused){yield return Foreground();yield return null;}t+=GameplayClock.Delta;yield return null;}}
 IEnumerator Until(Func<bool> test,float max=20){float t=0;while(!test()&&t<max){if(GamePause.IsPaused){yield return Foreground();yield return null;}t+=GameplayClock.Delta;yield return null;}Need(test(),"settled "+Status);}
 IEnumerator Hold(float seconds,params KeyCode[] keys){yield return Foreground();Input(keys);yield return Wait(seconds);Input();yield return Wait(.08f);}
 IEnumerator Pulse(KeyCode k){yield return Hold(.075f,k);yield return Wait(.18f);}
 IEnumerator Drain(Func<bool> busy=null){float t=0;var d=Rt.GetComponentInChildren<DialogueManager>(true);do{if(d.IsDialogueActive())yield return Pulse(KeyCode.E);else yield return Wait(.10f);t+=.25f;}while(t<60&&(d.IsDialogueActive()||busy!=null&&busy()));Need(!d.IsDialogueActive(),"original dialogue finished by E");Input();yield return Wait(.18f);}
 void Place(float x,float y){EndingSession.Place(Player,new Vector3(x,y,0));if(!Player.IsPlanarMovement)GroundedPlacement.Settle(Player);RoomPresentationFraming.PrepareCurrentView();}
 IEnumerator AdvanceUntil(Func<bool> reached,float max=45){float t=0;var d=Rt.GetComponentInChildren<DialogueManager>(true);while(!reached()&&t<max){if(d.IsDialogueActive())yield return Pulse(KeyCode.E);else yield return Wait(.10f);t+=.25f;}Need(reached(),"reached presentation cue "+Status);Input();}
 IEnumerator Shot(string label){Label(label);var cam=Camera.main;File.AppendAllText(folder+"/capture_state.txt",label+" camera="+(cam?cam.transform.position.ToString():"none")+" size="+(cam?cam.orthographicSize:0)+" target="+(cam&&cam.targetTexture?cam.targetTexture.name:"screen")+" active="+(RenderTexture.active?RenderTexture.active.name:"none")+" curtain="+(Chapter?Chapter.curtain.alpha:0)+" locked="+Controls.IsLocked()+" roots="+(Chapter?Chapter.homeRoot.activeSelf+"/"+Chapter.streetRoot.activeSelf+"/"+Chapter.maze.riverRoot.activeSelf:"other")+"\n");Canvas.ForceUpdateCanvases();P06EvidenceRecorder.ReserveStillFrame();yield return new WaitForEndOfFrame();var tex=ScreenCapture.CaptureScreenshotAsTexture();try{File.WriteAllBytes(folder+"/"+label+".png",tex.EncodeToPNG());}finally{Destroy(tex);}yield return Wait(.08f);}
 string[] BaseFlags(bool street)=>new[]{StoryFlag.Scene03Started.ToString(),StoryFlag.Scene03PhoneAnswered.ToString(),StoryFlag.Scene03IntroCompleted.ToString(),StoryFlag.Scene03CameraTaken.ToString()}.Concat(street?new[]{StoryFlag.Scene03StreetReached.ToString()}:new string[0]).ToArray();
 IEnumerator Fixture(string scene,Vector3 pos,string[] flags,bool camera=true,int revision=1,bool planar=false,Vector2Int cell=default){Label("fixture "+scene+" "+pos);Input();var d=JsonUtility.FromJson<GameSaveData>(JsonUtility.ToJson(baseline));d.scene=scene;d.actor=scene=="Scene03_Childhood"?"child":"adult";d.actorFacing="right";d.position=pos;d.planar=planar;d.scale=Vector3.one;d.companions=new SavedCompanion[0];d.story.flags=flags;d.story.mazeCell=cell;d.items=new SavedItem[0];d.files=new SavedFile[0];d.school=new SavedSchool();d.cameraAvailable=camera;d.lampRaised=false;d.childhoodLayoutRevision=revision;d.courtyardLayoutRevision=3;d.cameraSize=2.2f;d.cameraPosition=new Vector3(pos.x,pos.y<5?2.05f:pos.y<50?32.05f:72.05f,-10);d.cameraX=new Vector2(-35,315);d.cameraY=new Vector2(-5,130);d.followY=planar;if(camera){var item=(ItemData)Field(Rt.GetComponent<CameraModeController>(),"requiredItem");d.items=new[]{new SavedItem{key=SaveAssetRegistry.Load().Key(item),id=item.itemId,displayName=item.itemName,description=item.description}};}saves.Store.Write(1,d,true);Need(saves.Load(1,out var err),"fixture original loader "+err);float end=Time.realtimeSinceStartup+35;while(saves.IsRestoring&&Time.realtimeSinceStartup<end)yield return null;Need(!saves.IsRestoring&&saves.LastError==null,"load completed "+saves.LastError);yield return Foreground();yield return Wait(.5f);Need(GroundedPlacement.IsSupported(Player),"actor supported or valid planar ground");}
 IEnumerator SaveLoad(string name){yield return Until(()=>saves.CanSave(out _));var x=Player.transform.position;Need(saves.Save(2,true,out var e),"save free action "+name+" "+e);Need(saves.Load(2,out e),"reload "+name+" "+e);yield return Until(()=>!saves.IsRestoring,35);Need(saves.LastError==null,"restore "+name);yield return Wait(.6f);Check(Vector3.Distance(Player.transform.position,x)<.2f,"position preserved "+name);yield return Shot(name);}
 IEnumerator Door(string suffix){var d=T(suffix).GetComponent<RoomTransitionInteractable>();Need(d,"original door binding "+suffix);Label("door "+suffix);Place(d.transform.position.x,Player.transform.position.y);bool arrived=false;Action<RoomTransitionInteractable> reached=_=>arrived=true;d.Arrived+=reached;try{d.Interact();yield return Wait(.15f);yield return Until(()=>arrived);}finally{d.Arrived-=reached;}Check(GroundedPlacement.IsSupported(Player),"door destination supported");}


 IEnumerator InteractionTests(){yield return Foreground();yield return Drain();yield return Until(()=>saves.CanSave(out _));baseline=saves.Capture(1);yield return Fixture("Scene03_Childhood",new Vector3(-12,1.23f),new[]{StoryFlag.Scene03Started.ToString()},false);var ch=Chapter;ch.Interact(ChildhoodAction.Phone);yield return Wait(.2f);yield return Drain(()=>ch.Busy);yield return Door("Home_Floor01_Normal/S03_LivingRoomDoor");var targets=FindObjectsByType<Scene03Interactable>(FindObjectsSortMode.None).Where(i=>i.action==ChildhoodAction.Camera||i.action==ChildhoodAction.Parents).ToArray();foreach(var target in targets){var c=target.GetComponent<Collider2D>();var r=target.GetComponent<InteractionReach>();var h=target.GetComponent<HandDrawnInteractionHighlight>();Bounds b=c.bounds;if(h&&h.TryGetInteractionBounds(out var bb))b=bb;File.AppendAllText(folder+"/interaction-probe.txt",target.action+" pos="+target.transform.position+" sensor="+c.bounds+" surface="+b+" anchor="+(r&&r.anchor?r.anchor.position.ToString():"none")+" visual="+(r&&r.visualSurface?r.visualSurface.bounds.ToString():"none")+" reach="+(r?r.horizontalReach+"/"+r.verticalReach:"default")+" layer="+target.gameObject.layer+" trigger="+c.isTrigger+"\n");}
 int cameraSelections=0;for(float x=197.5f;x<202.5f;x+=.10f){Place(x,Player.transform.position.y);yield return Wait(.04f);var pi=Player.GetComponent<PlayerInteraction>();var t=pi.CurrentVisualTarget as Scene03Interactable;if(t&&t.action==ChildhoodAction.Camera)cameraSelections++;File.AppendAllText(folder+"/interaction-probe.txt","x="+x+" feet="+pi.Feet+" target="+(t?t.action.ToString():pi.CurrentVisualTarget?.GetType().Name??"none")+"\n");}Check(cameraSelections>0,"Camera reachable through real target selection "+cameraSelections);Place(200.0f,Player.transform.position.y);yield return Wait(.15f);Check((Player.GetComponent<PlayerInteraction>().CurrentVisualTarget as Scene03Interactable)?.action==ChildhoodAction.Camera,"Tabletop camera prompt is selected at the painted camera");yield return Shot("LivingRoom_CameraPrompt");yield return Pulse(KeyCode.E);yield return Drain(()=>ch.Busy);Check(Story.Has(StoryFlag.Scene03CameraTaken),"Real E acquires camera near parents without direct camera API");Check(string.IsNullOrEmpty(targets.First(t=>t.action==ChildhoodAction.Camera).GetInteractionPrompt()),"Taken camera removes stale pickup prompt");Place(199.15f,Player.transform.position.y);yield return Wait(.15f);Check((Player.GetComponent<PlayerInteraction>().CurrentVisualTarget as Scene03Interactable)?.action==ChildhoodAction.Parents,"Parents still have their own reachable dialogue");yield return Pulse(KeyCode.Q);yield return Wait(.7f);Check(Rt.GetComponent<CameraModeController>().IsRaised,"E-acquired camera raises through original Q");yield return Shot("LivingRoom_CameraRaised_AfterE");yield return Pulse(KeyCode.Q);yield return Wait(.7f);yield return Fixture("Scene03_Childhood",new Vector3(200.9f,1.23f),new[]{StoryFlag.Scene03Started.ToString(),StoryFlag.Scene03PhoneAnswered.ToString(),StoryFlag.Scene03IntroCompleted.ToString()},false);ch=Chapter;Input(KeyCode.A);yield return Until(()=>(Player.GetComponent<PlayerInteraction>().CurrentVisualTarget as Scene03Interactable)?.action==ChildhoodAction.Camera,5);Input();yield return Wait(.1f);yield return Pulse(KeyCode.E);yield return Drain(()=>ch.Busy);Check(Story.Has(StoryFlag.Scene03CameraTaken),"Right-side actual movement and E acquire camera");}
 void Probe(string label){var cm=Rt.GetComponent<CameraModeController>();var tm=Rt.GetComponent<P02ToolMotion>();var ap=Player.GetComponent<P02ActorPresentation>();File.AppendAllText(folder+"/probe.txt",label+" scene="+SceneManager.GetActiveScene().name+" player="+Player.name+" owns="+(ap&&ap.OwnsBody)+" direction="+(ap?ap.Direction:"")+" context="+cm.ContextAvailable+" can="+cm.CanBeginPresentation+" busy="+cm.IsBusy+" raised="+cm.IsRaised+" tool="+tm.Current+"/"+tm.Desired+"/"+tm.State+" blend="+tm.Blend+" blocked="+GameplayInput.Blocked+" locks="+string.Join(",",Enum.GetValues(typeof(ControlLockReason)).Cast<ControlLockReason>().Where(Controls.IsLockedBy))+"\n");}
